def _load_buildcommand_app():
    runtime_root = Path(os.environ.get("BUILDCOMMAND_RUNTIME_DIR", "/tmp/buildcommand_1_8_17_5_runtime"))
    marker = runtime_root / ".ready"
    expected = runtime_root / "full_app.py"
    parts = runtime_root / "buildcommand_parts"
    if not marker.exists() or marker.read_text(errors="ignore").strip() != "1.8.17.5" or not expected.exists() or not parts.exists():
        import shutil
        shutil.rmtree(runtime_root, ignore_errors=True)
        runtime_root.mkdir(parents=True, exist_ok=True)
        data = base64.b85decode(PAYLOAD.encode("ascii"))
        with zipfile.ZipFile(io.BytesIO(data), "r") as z:
            z.extractall(runtime_root)
        marker.write_text("1.8.17.5", encoding="utf-8")
    spec = importlib.util.spec_from_file_location("buildcommand_runtime_app_1875", expected)
    if spec is None or spec.loader is None:
        raise RuntimeError("Unable to load extracted BuildCommand application")
    module = importlib.util.module_from_spec(spec)
    old_path = list(sys.path)
    try:
        sys.path.insert(0, str(runtime_root))
        spec.loader.exec_module(module)
    finally:
        sys.path[:] = old_path
    return module

