from fastapi.responses import HTMLResponse as _BC176_HTMLResponse, JSONResponse as _BC176_JSONResponse
from datetime import datetime as _BC176_datetime

def _bc176_init():
    c=_runtime.db()
    c.executescript('''
    CREATE TABLE IF NOT EXISTS platform_revenue_snapshots(
        id INTEGER PRIMARY KEY,
        snapshot_month TEXT NOT NULL,
        mrr_cents INTEGER DEFAULT 0,
        arr_cents INTEGER DEFAULT 0,
        active_customers INTEGER DEFAULT 0,
        trial_customers INTEGER DEFAULT 0,
        past_due_customers INTEGER DEFAULT 0,
        canceled_customers INTEGER DEFAULT 0,
        failed_payments INTEGER DEFAULT 0,
        ai_requests INTEGER DEFAULT 0,
        blueprint_runs INTEGER DEFAULT 0,
        document_uploads INTEGER DEFAULT 0,
        storage_bytes INTEGER DEFAULT 0,
        created TEXT
    );
    CREATE TABLE IF NOT EXISTS platform_usage_events(
        id INTEGER PRIMARY KEY,
        company_id INTEGER NOT NULL,
        event_type TEXT NOT NULL,
        quantity REAL DEFAULT 1,
        metadata_json TEXT,
        created TEXT
    );
    ''')
    c.commit(); c.close()

_bc176_init()

def _bc176_rowdict(row):
    if row is None: return {}
    try: return dict(row)
    except Exception:
        return {k: row[k] for k in row.keys()}

def _bc176_metrics():
    c=_runtime.db()
    plans={r["code"]:r for r in c.execute("SELECT * FROM platform_plans WHERE COALESCE(active,1)=1").fetchall()}
    subs=c.execute("SELECT * FROM company_subscriptions").fetchall()
    companies=c.execute("SELECT COUNT(*) n FROM companies").fetchone()["n"]
    active=trials=past_due=canceled=0
    mrr=0
    for s in subs:
        try: status=_runtime._bc174_effective_status(s)
        except Exception: status=str(s["status"] or "").upper()
        if status=="ACTIVE":
            active+=1
            p=plans.get(s["plan_code"])
            if p: mrr+=int(p["monthly_price_cents"] or 0)
        elif status=="TRIAL":
            trials+=1
        elif status=="PAST_DUE":
            past_due+=1
        elif status=="CANCELED":
            canceled+=1
        elif status=="LEGACY":
            active+=1

    month=_BC176_datetime.utcnow().strftime("%Y-%m")
    usage=c.execute('''SELECT
        COALESCE(SUM(ai_requests),0) ai_requests,
        COALESCE(SUM(blueprint_runs),0) blueprint_runs,
        COALESCE(SUM(document_uploads),0) document_uploads,
        COALESCE(SUM(storage_bytes),0) storage_bytes
        FROM platform_usage_monthly WHERE usage_month=?''',(month,)).fetchone()
    failed=c.execute('''SELECT COUNT(*) n FROM billing_events
        WHERE lower(COALESCE(status,'')) IN ('failed','past_due','unpaid')
           OR lower(COALESCE(event_type,'')) = 'payment_failed' ''').fetchone()["n"]

    customer_rows=c.execute('''SELECT co.id,co.name,
        (SELECT COUNT(*) FROM users u WHERE u.company_id=co.id) seats_used,
        (SELECT COUNT(*) FROM projects p WHERE p.company_id=co.id) projects_used,
        cs.plan_code,cs.status,cs.seat_limit_override,cs.project_limit_override
        FROM companies co LEFT JOIN company_subscriptions cs ON cs.company_id=co.id
        ORDER BY co.name''').fetchall()
    customers=[]
    for r in customer_rows:
        plan=plans.get(r["plan_code"]) if r["plan_code"] else None
        seat_limit=(r["seat_limit_override"] if r["seat_limit_override"] is not None else (plan["seat_limit"] if plan else 0)) or 0
        project_limit=(r["project_limit_override"] if r["project_limit_override"] is not None else (plan["project_limit"] if plan else 0)) or 0
        seat_pct=round((float(r["seats_used"])/seat_limit)*100,1) if seat_limit else 0
        project_pct=round((float(r["projects_used"])/project_limit)*100,1) if project_limit else 0
        customers.append({
            "company_id":r["id"],"company_name":r["name"],"plan":r["plan_code"] or "—","status":r["status"] or "—",
            "seats_used":r["seats_used"],"seat_limit":seat_limit,"seat_utilization_pct":seat_pct,
            "projects_used":r["projects_used"],"project_limit":project_limit,"project_utilization_pct":project_pct
        })
    c.close()
    return {
        "month":month,"companies":companies,"mrr_cents":mrr,"arr_cents":mrr*12,
        "active_customers":active,"trial_customers":trials,"past_due_customers":past_due,
        "canceled_customers":canceled,"failed_payments":failed,
        "ai_requests":int(usage["ai_requests"] or 0),"blueprint_runs":int(usage["blueprint_runs"] or 0),
        "document_uploads":int(usage["document_uploads"] or 0),"storage_bytes":int(usage["storage_bytes"] or 0),
        "customers":customers
    }

def _bc176_money(cents):
    return f"${(int(cents or 0)/100):,.2f}"

@app.get("/platform/revenue", response_class=_BC176_HTMLResponse)
def platform_revenue_dashboard():
    if not _runtime._bc174_is_platform_owner():
        return _BC176_HTMLResponse("Platform owner access required.",status_code=403)
    m=_bc176_metrics()
    rows=""
    for r in m["customers"]:
        seat=f'{r["seats_used"]}/{r["seat_limit"] or "∞"}'
        proj=f'{r["projects_used"]}/{r["project_limit"] or "∞"}'
        rows+=f'<tr><td>{_runtime.esc(r["company_name"])}</td><td>{_runtime.esc(r["plan"])}</td><td>{_runtime.esc(r["status"])}</td><td>{seat} ({r["seat_utilization_pct"]}%)</td><td>{proj} ({r["project_utilization_pct"]}%)</td></tr>'
    body=f'''
    <div class="hero"><div class="eyebrow">PLATFORM OWNER</div><h1>Revenue & Usage</h1>
    <p class="muted">Subscription revenue, customer lifecycle, capacity utilization, and product usage for {m["month"]}.</p></div>
    <div class="grid4">
      <div class="card"><div class="label">MRR</div><div class="kpi">{_bc176_money(m["mrr_cents"])}</div></div>
      <div class="card"><div class="label">ARR Run Rate</div><div class="kpi">{_bc176_money(m["arr_cents"])}</div></div>
      <div class="card"><div class="label">Active Customers</div><div class="kpi">{m["active_customers"]}</div></div>
      <div class="card"><div class="label">Trials</div><div class="kpi">{m["trial_customers"]}</div></div>
    </div>
    <div class="grid4">
      <div class="card"><div class="label">Past Due</div><div class="kpi">{m["past_due_customers"]}</div></div>
      <div class="card"><div class="label">Canceled</div><div class="kpi">{m["canceled_customers"]}</div></div>
      <div class="card"><div class="label">Failed Payments</div><div class="kpi">{m["failed_payments"]}</div></div>
      <div class="card"><div class="label">Companies</div><div class="kpi">{m["companies"]}</div></div>
    </div>
    <div class="grid4">
      <div class="card"><div class="label">AI Requests</div><div class="kpi">{m["ai_requests"]}</div></div>
      <div class="card"><div class="label">Blueprint Runs</div><div class="kpi">{m["blueprint_runs"]}</div></div>
      <div class="card"><div class="label">Uploads</div><div class="kpi">{m["document_uploads"]}</div></div>
      <div class="card"><div class="label">Storage</div><div class="kpi">{m["storage_bytes"]/(1024**3):.2f} GB</div></div>
    </div>
    <div class="card"><h2>Customer Utilization</h2><table><thead><tr><th>Company</th><th>Plan</th><th>Status</th><th>Seats</th><th>Projects</th></tr></thead>
    <tbody>{rows or '<tr><td colspan="5">No customers yet.</td></tr>'}</tbody></table></div>
    '''
    return _runtime.shell("Revenue & Usage",body)

